import React from "react";
import CartContext from "./CartContext";
import { useState } from "react";

const CartProvider = (props) => {
  const [openCart, setOpenCart] = useState(false);
  const [items, setItems] = useState([]);
  const [totalAmount, setTotalAmount] = useState(0);

 // const totalQuantity = items.reduce((acc, item) => acc + item.amount, 0);

  const openCartHandler = () => {
    setOpenCart(true);
  };
  const closeCartHandler = () => {
    setOpenCart(false);
  };

  const addItemToCart = (item) => {
    const existingItemIndex = items.findIndex((i) => i.id === item.id);
    if (existingItemIndex !== -1) {
      const updatedItems = [...items];
      updatedItems[existingItemIndex].amount += item.amount;
      setItems(updatedItems);
      setTotalAmount(
        (prevTotalAmount) => prevTotalAmount + item.price * item.amount,
      );
    } else {
      setItems((prevItems) => [...prevItems, { ...item, amount: item.amount }]);
      setTotalAmount(
        (prevTotalAmount) => prevTotalAmount + item.price * item.amount,
      );
    }
  };
  const removeItemHandler = (id) => {};

  const contextObject = {
    items: items,
    quantity: totalQuantity,
    openCart,
    totalAmount: totalAmount,
    addItem: addItemToCart,
    removeItem: removeItemHandler,
    openCartHandler,
    closeCartHandler,
  };
  return (
    <CartContext.Provider value={contextObject}>
      {props.children}
    </CartContext.Provider>
  );
};
export default CartProvider;
